import {
  ConversationFeedbackDialog,
  type FeedbackDialogRef,
} from '@github-ui/copilot-chat/components/ConversationFeedbackDialog'
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {useSelectedCopilotSpaceId} from '@github-ui/copilot-chat/hooks/use-selected-custom-copilot-id'
import {COPILOT_SPACES_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import type {CopilotSpace} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {findCustomCopilot} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {CreateSpaceDialog} from '@github-ui/copilot-spaces/components/CreateSpaceDialog'
import {ReportSpaceDialog} from '@github-ui/copilot-spaces/components/ReportSpaceDialog'
import {useDeleteCopilotSpace, useFetchCopilotSpace, useReportUrl} from '@github-ui/copilot-spaces/hooks'
import type {CopilotSpacesConfigPayload} from '@github-ui/copilot-spaces/types'
import {sendEvent} from '@github-ui/hydro-analytics'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {useLocation} from '@github-ui/react-router'
import {testIdProps} from '@github-ui/test-id-props'
import {useNavigate} from '@github-ui/use-navigate'
import {
  AlertIcon,
  BookIcon,
  CopyIcon,
  KebabHorizontalIcon,
  ReportIcon,
  ShareIcon,
  StarFillIcon,
  StarIcon,
  TrashIcon,
} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, Flash, IconButton} from '@primer/react'
import {useEffect, useMemo, useRef, useState} from 'react'

import {Header} from '../Header'
import {useGlobalNavigation} from './hooks/use-global-navigation'
import {useStarCopilotSpace} from './hooks/use-star-copilot-space'
import {DeleteDialog} from './SpaceMenu'
import {SpaceSharingDialog} from './SpaceSharingDialog'
import styles from './SpacesHeader.module.css'
import {DescriptionDialog} from './v3/components/DescriptionDialog'

// copilotSpace prop only used for tests
export function SpacesHeader({copilotSpace}: {copilotSpace?: CopilotSpace}) {
  const state = useChatState()
  const {optedInToUserFeedback} = state
  const manager = useChatManager()
  const location = useLocation()
  const selectedCopilotSpaceId = useSelectedCopilotSpaceId()
  const {updateGlobalNavigationBreadcrumbs} = useGlobalNavigation()
  const navigate = useNavigate()
  const [showDeleteSpaceDialog, setShowDeleteSpaceDialog] = useState(false)
  const [showShareSpaceDialog, setShowShareSpaceDialog] = useState(false)
  const [showDescriptionDialog, setShowDescriptionDialog] = useState(false)
  const [showDuplicateSpaceDialog, setShowDuplicateSpaceDialog] = useState(false)
  const [showReportSpaceDialog, setShowReportSpaceDialog] = useState(false)
  const [deletionError, setDeletionError] = useState<Error | null>(null)
  const headerButtonRef = useRef<HTMLButtonElement>(null)
  const shareButtonRef = useRef<HTMLButtonElement>(null)
  const [breadcrumbMenuRef, setBreadcrumbMenuRef] = useState<React.RefObject<HTMLButtonElement | null> | null>(null)
  const feedbackRef = useRef<FeedbackDialogRef>(null)
  const anchorRef = useRef<HTMLButtonElement>(null)
  const pathname = location.pathname
  const isCopilotSpaceDetail = selectedCopilotSpaceId && pathname !== COPILOT_SPACES_PATH
  const {data: selectedCopilotSpace} = useFetchCopilotSpace(selectedCopilotSpaceId)
  const {mutateAsync: deleteCopilotSpace} = useDeleteCopilotSpace()
  const {
    copilotSpacesConfig: {maxDescriptionLength},
  } = useAppPayload<CopilotSpacesConfigPayload>()

  const copilot = useMemo(
    () => copilotSpace ?? selectedCopilotSpace ?? findCustomCopilot(state.customCopilots, selectedCopilotSpaceId),
    [state.customCopilots, copilotSpace, selectedCopilotSpaceId, selectedCopilotSpace],
  )

  const orgOwnedSharingEnabled = copilot?.ownerIsOrg && copilot?.adminable
  const userOwnedSharingEnabled = !copilot?.ownerIsOrg && selectedCopilotSpaceId && copilot?.adminable
  const sharingEnabled = orgOwnedSharingEnabled || userOwnedSharingEnabled

  // Show report button for spaces that are not owned by the current user and are public/shared
  const isOrgPublicOrShared = copilot?.ownerIsOrg && (copilot.baseRole !== 'none' || copilot.collaborative)
  const reportingEnabled = Boolean(copilot && selectedCopilotSpaceId && (isOrgPublicOrShared || copilot?.shared))
  const reportUrl = useReportUrl(selectedCopilotSpaceId)

  const {starCopilotSpace, isLoading} = useStarCopilotSpace(copilot as CopilotSpace)

  useEffect(() => {
    // Close dialogs when the space changes. This fixes an issue when using the back button to
    // navigate between recent spaces. https://github.com/github/copilot-experiences/issues/7261
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setShowDuplicateSpaceDialog(false)
    setShowDeleteSpaceDialog(false)
    setShowShareSpaceDialog(false)
    setShowDescriptionDialog(false)
    setShowReportSpaceDialog(false)
  }, [selectedCopilotSpaceId])

  useEffect(() => {
    updateGlobalNavigationBreadcrumbs()
  }, [updateGlobalNavigationBreadcrumbs])

  const closeDuplicateSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_DUPLICATE_DIALOG_CLOSE', mode: 'immersive'})
    setShowDuplicateSpaceDialog(false)
  }

  const closeShareSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_SHARE_DIALOG_CLOSE', mode: 'immersive'})
    setShowShareSpaceDialog(false)
  }

  const closeDeleteSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_DELETE_DIALOG_CLOSE', mode: 'immersive'})
    setShowDeleteSpaceDialog(false)
  }

  const closeReportSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_REPORT_DIALOG_CLOSE', mode: 'immersive'})
    setShowReportSpaceDialog(false)
  }

  const openDuplicateSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_DUPLICATE', mode: 'immersive'})
    setShowDuplicateSpaceDialog(true)
  }

  const openShareSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_SHARE', mode: 'immersive'})
    setShowShareSpaceDialog(true)
  }

  const openDeleteSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_DELETE', mode: 'immersive'})
    setShowDeleteSpaceDialog(true)
  }

  const openReportSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_REPORT', mode: 'immersive'})
    setShowReportSpaceDialog(true)
  }

  const deleteSpace = async () => {
    if (selectedCopilotSpaceId) {
      try {
        await deleteCopilotSpace(selectedCopilotSpaceId)
        setShowDeleteSpaceDialog(false)
        navigate(COPILOT_SPACES_PATH)
      } catch (err) {
        setDeletionError(err instanceof Error ? err : new Error(String(err)))
        closeDeleteSpaceDialog()
      }
    }
  }

  const handleStarClick = () => {
    if (copilot && starCopilotSpace) {
      sendEvent('dotcom_chat.activate', {
        target: copilot.starred ? 'SPACE_UNSTAR' : 'SPACE_STAR',
        mode: 'immersive',
      })
      void starCopilotSpace({starred: !copilot.starred})
    }
  }

  const adminable = copilot?.adminable

  const deleteSpaceButton = adminable && (
    <ActionList.Item variant="danger" onSelect={openDeleteSpaceDialog}>
      <ActionList.LeadingVisual>
        <TrashIcon />
      </ActionList.LeadingVisual>
      Delete
    </ActionList.Item>
  )

  const duplicateSpaceButton = copilot && (
    <ActionList.Item onSelect={openDuplicateSpaceDialog}>
      <ActionList.LeadingVisual>
        <CopyIcon />
      </ActionList.LeadingVisual>
      Duplicate
    </ActionList.Item>
  )

  const spaceSpecificItems =
    isCopilotSpaceDetail && !state.selectedThreadID && (duplicateSpaceButton || deleteSpaceButton) ? (
      <>
        {duplicateSpaceButton}
        {deleteSpaceButton}
      </>
    ) : null

  const feedbackButton = optedInToUserFeedback ? (
    <Button
      variant="link"
      onClick={() => {
        feedbackRef.current?.openDialog()
        sendEvent('dotcom_chat.activate', {
          target: 'USER_MENU_GIVE_FEEDBACK',
          mode: 'immersive',
        })
      }}
    >
      Give feedback
    </Button>
  ) : null

  const shareButton = sharingEnabled && (
    /* TODO: Should indicate visibility state via icon and aria-label for v3 FF */
    <IconButton
      ref={shareButtonRef}
      icon={ShareIcon}
      onClick={openShareSpaceDialog}
      variant="invisible"
      aria-label="Share space"
      {...testIdProps('share-space-button')}
    />
  )

  const reportButton = reportingEnabled && (
    <IconButton
      icon={ReportIcon}
      onClick={openReportSpaceDialog}
      variant="invisible"
      aria-label="Report space content"
      {...testIdProps('report-space-button')}
    />
  )

  const favButton = copilot && selectedCopilotSpaceId && (
    <IconButton
      ref={headerButtonRef}
      onClick={handleStarClick}
      disabled={isLoading}
      icon={copilot.starred ? StarFillIcon : StarIcon}
      className={copilot.starred ? styles.starButton : undefined}
      variant="invisible"
      aria-label={copilot.starred ? 'Unstar space' : 'Star space'}
    />
  )

  const handleFeedbackClick = () => {
    feedbackRef.current?.openDialog()
    sendEvent('dotcom_chat.activate', {
      target: 'USER_MENU_GIVE_FEEDBACK',
      mode: 'immersive',
    })
  }

  const handleDocsClick = () => {
    sendEvent('copilot-spaces.click', {target: 'HELP_BUTTON_CLICKED'})
  }

  const docsUrl =
    'https://docs.github.com/copilot/how-tos/provide-context/use-copilot-spaces/create-and-use-copilot-spaces'

  const customButtonsContent = (
    <>
      {feedbackButton}
      <IconButton
        icon={BookIcon}
        as="a"
        href="https://docs.github.com/copilot/how-tos/provide-context/use-copilot-spaces/create-and-use-copilot-spaces"
        aria-label="Copilot Spaces documentation"
        target="_blank"
        rel="noopener noreferrer"
        variant="invisible"
        onClick={() => sendEvent('copilot-spaces.click', {target: 'HELP_BUTTON_CLICKED'})}
        {...testIdProps('spaces-doc-link')}
      />
      {shareButton}
      {reportButton}
      {favButton}
    </>
  )

  const customButtonsMenu = (
    <>
      <ActionList.LinkItem href={docsUrl} target="_blank" rel="noopener noreferrer" onSelect={handleDocsClick}>
        <ActionList.LeadingVisual>
          <BookIcon />
        </ActionList.LeadingVisual>
        Copilot Spaces documentation
      </ActionList.LinkItem>
      {sharingEnabled && (
        <ActionList.Item onSelect={openShareSpaceDialog}>
          <ActionList.LeadingVisual>
            <ShareIcon />
          </ActionList.LeadingVisual>
          Share space
        </ActionList.Item>
      )}
      {reportingEnabled && (
        <ActionList.Item onSelect={openReportSpaceDialog}>
          <ActionList.LeadingVisual>
            <ReportIcon />
          </ActionList.LeadingVisual>
          Report space content
        </ActionList.Item>
      )}
      {copilot && selectedCopilotSpaceId && (
        <ActionList.Item onSelect={handleStarClick} disabled={isLoading}>
          <ActionList.LeadingVisual>{copilot.starred ? <StarFillIcon /> : <StarIcon />}</ActionList.LeadingVisual>
          {copilot.starred ? 'Unstar space' : 'Star space'}
        </ActionList.Item>
      )}
      <ActionList.Divider />
      <ActionList.Item onSelect={handleFeedbackClick}>Give feedback</ActionList.Item>
    </>
  )

  const customButtons = (
    <>
      <div className={styles.hideOnMobile}>{customButtonsContent}</div>
      <div className={styles.showOnMobile}>
        <ActionMenu>
          <ActionMenu.Anchor>
            <IconButton icon={KebabHorizontalIcon} aria-label="Space options" variant="invisible" />
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList>{customButtonsMenu}</ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>
    </>
  )

  const handleDescriptionSaved = (updatedSpace: CopilotSpace) => {
    manager.dispatch({type: 'SET_CUSTOM_COPILOT', customCopilot: updatedSpace})
  }

  return (
    <>
      <Header
        showPreviewPaneButton={false}
        conversationSpecificItems={spaceSpecificItems}
        customButtons={customButtons}
        defaultName={copilot?.name || ''}
        onBreadcrumbMenuRefReady={setBreadcrumbMenuRef}
      />
      {deletionError && (
        <Flash variant="danger">
          <AlertIcon />
          There was a problem deleting your space.
        </Flash>
      )}

      {showDuplicateSpaceDialog && selectedCopilotSpace ? (
        <CreateSpaceDialog
          dialogTitle="Duplicate Space"
          closeDialog={closeDuplicateSpaceDialog}
          initialSpace={selectedCopilotSpace}
          returnFocusRef={breadcrumbMenuRef}
        />
      ) : null}

      {showDeleteSpaceDialog && selectedCopilotSpaceId ? (
        <DeleteDialog onCancel={closeDeleteSpaceDialog} onConfirm={deleteSpace} returnFocusRef={breadcrumbMenuRef} />
      ) : null}
      {showShareSpaceDialog && selectedCopilotSpaceId ? (
        <SpaceSharingDialog
          closeDialog={closeShareSpaceDialog}
          customCopilotId={selectedCopilotSpaceId}
          userOwned={Boolean(!orgOwnedSharingEnabled && userOwnedSharingEnabled)}
          returnFocusRef={shareButtonRef}
        />
      ) : null}
      {showDescriptionDialog && copilot ? (
        <DescriptionDialog
          copilotSpace={copilot as CopilotSpace}
          onClose={() => setShowDescriptionDialog(false)}
          returnFocusRef={headerButtonRef}
          maxDescriptionLength={maxDescriptionLength}
          onSaved={handleDescriptionSaved}
        />
      ) : null}
      {showReportSpaceDialog && copilot && selectedCopilotSpaceId ? (
        <ReportSpaceDialog reportUrl={reportUrl} onClose={closeReportSpaceDialog} />
      ) : null}

      <ConversationFeedbackDialog ref={feedbackRef} mode="immersive" returnFocusRef={anchorRef} />
    </>
  )
}
