import {useDebounce} from '@github-ui/use-debounce'
import {SearchIcon, XCircleFillIcon} from '@primer/octicons-react'
import {FormControl, IconButton, TextInput} from '@primer/react'
import {useState} from 'react'

import styles from './SearchInput.module.css'

export interface SearchInputProps {
  onSearch: (query: string) => void
  placeholder?: string
  'aria-label'?: string
  disabled?: boolean
  /**
   * Delay in milliseconds before triggering search. Defaults to 200ms.
   */
  debounceDelay?: number
}

export function SearchInput({
  onSearch,
  placeholder = 'Search...',
  'aria-label': ariaLabel = 'Search',
  disabled = false,
  debounceDelay = 200,
}: SearchInputProps) {
  const [searchQuery, setSearchQuery] = useState('')

  // Debounce the search to avoid excessive filtering on every keystroke
  const debouncedSearch = useDebounce(onSearch, debounceDelay)

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newQuery = e.currentTarget.value
    setSearchQuery(newQuery)

    // For empty queries, search immediately to clear results
    if (newQuery.trim() === '') {
      onSearch('')
    } else {
      debouncedSearch(newQuery)
    }
  }

  const clearSearch = () => {
    setSearchQuery('')
    onSearch('')
  }

  return (
    <div className={styles.searchContainer}>
      <FormControl className={styles.searchInputWrapper} disabled={disabled}>
        <FormControl.Label visuallyHidden>{ariaLabel}</FormControl.Label>
        <TextInput
          className={styles.searchInput}
          placeholder={placeholder}
          value={searchQuery}
          onChange={handleChange}
          leadingVisual={SearchIcon}
          trailingAction={
            searchQuery !== '' ? (
              <IconButton
                icon={XCircleFillIcon}
                onClick={clearSearch}
                aria-label="Clear search"
                variant="invisible"
                size="small"
                disabled={disabled}
              />
            ) : undefined
          }
        />
      </FormControl>
    </div>
  )
}
