import {useChatStateValues} from '@github-ui/copilot-chat/CopilotChatContext'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {sendEvent} from '@github-ui/hydro-analytics'
import {LightBulbIcon} from '@primer/octicons-react'
import {Button, Popover} from '@primer/react'
import {useCallback, useEffect, useState} from 'react'

import styles from './SpacesConversation.module.css'

const DEFAULT_MAX_DISMISSALS = 2

interface DismissablePopoverProps {
  children: React.ReactNode
  popoverBody: React.ReactNode
  maxDismissals?: number
}

export function DismissablePopover({
  children,
  popoverBody,
  maxDismissals = DEFAULT_MAX_DISMISSALS,
}: DismissablePopoverProps) {
  const {mode} = useChatStateValues('mode')
  const [isDismissed, setIsDismissed] = useState(
    () => copilotLocalStorage.getSpacesSourcesTipDismissalCount() >= maxDismissals,
  )

  useEffect(() => {
    if (!isDismissed) {
      sendEvent('dotcom_chat.activate', {target: 'SPACES_SOURCES_TIP', action: 'shown', mode})
    }
  }, [isDismissed, mode])

  const handleDismiss = useCallback(() => {
    const current = copilotLocalStorage.getSpacesSourcesTipDismissalCount()
    copilotLocalStorage.setSpacesSourcesTipDismissalCount(current + 1)
    setIsDismissed(true)
    sendEvent('dotcom_chat.activate', {
      target: 'SPACES_SOURCES_TIP',
      action: 'dismiss',
      mode,
    })
  }, [mode])

  return (
    <div className={styles.attachButton} data-tip-dismissed={isDismissed || undefined}>
      {children}
      <Popover open caret="top-right" className={styles.sourcesPopover}>
        <Popover.Content className={styles.sourcesPopoverContent}>
          <div className={styles.sourcesPopoverBody}>
            <LightBulbIcon size={16} className={styles.sourcesPopoverIcon} />
            {popoverBody}
          </div>
          <Button size="small" onClick={handleDismiss}>
            Got it
          </Button>
        </Popover.Content>
      </Popover>
    </div>
  )
}
