import {updateSearchParams} from '@github-ui/history'
import {ssrSafeWindow} from '@github-ui/ssr-utils'
import {useEffect} from 'react'

import {useChatStateValues} from '../../../utils/CopilotChatContext'
import {useTraceManager} from '../TraceManagerContext'

const OPEN_TRACE_PARAM = 'open_trace'

/**
 * Opens the trace viewer for the routed thread when immersive is launched with `?open_trace=1`.
 * Used to deep-link into a trace from the contextual chat "View trace" action.
 */
export function useOpenTraceFromUrl() {
  const traceManager = useTraceManager()
  const {selectedThreadID} = useChatStateValues('selectedThreadID')

  useEffect(() => {
    if (!ssrSafeWindow || !selectedThreadID) return

    const url = new URL(ssrSafeWindow.location.href, ssrSafeWindow.location.origin)
    if (url.searchParams.get(OPEN_TRACE_PARAM) !== '1') return

    // Only open once the routed thread has actually loaded, so we never reveal a stale thread's trace.
    if (!url.pathname.endsWith(`/c/${selectedThreadID}`)) return

    void traceManager.showTraceDisplay(true, selectedThreadID)

    url.searchParams.delete(OPEN_TRACE_PARAM)
    updateSearchParams(url.searchParams)
  }, [selectedThreadID, traceManager])
}
