import ProductAnnouncement from '@github-ui/product-announcement/components/ProductAnnouncement'
import {useAnalytics, useClickAnalytics} from '@github-ui/use-analytics'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useCallback, useEffect, useRef} from 'react'

const TAB_TITLES = ['Set up Copilot', 'Plan, delegate, or manage work', 'Customize your agent']

interface CopilotWelcomeModalProps {
  showCopilotWelcomeModal: boolean
  currentUserLogin: string
  copilotPlanName?: string
  nudgeCategory: string
  dismissPath?: string
}

export function CopilotWelcomeModal({
  showCopilotWelcomeModal,
  currentUserLogin,
  copilotPlanName,
  nudgeCategory,
  dismissPath,
}: CopilotWelcomeModalProps) {
  const activeTabIndexRef = useRef(0)
  const {sendAnalyticsEvent} = useAnalytics()
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const analyticsLabel = `nudge_id:accelerate_ipm_copilot_business_onboarding_modal;nudge_category:${nudgeCategory};user:${currentUserLogin};plan:${copilotPlanName ?? ''};`

  const sendAnalytics = useCallback(
    (action: string) => {
      sendClickAnalyticsEvent({
        category: nudgeCategory,
        action,
        label: analyticsLabel,
      })
    },
    [sendClickAnalyticsEvent, analyticsLabel, nudgeCategory],
  )

  useEffect(() => {
    if (showCopilotWelcomeModal) {
      sendAnalyticsEvent('analytics.visible', undefined, {
        category: nudgeCategory,
        action: 'visible',
        label: analyticsLabel,
      })
    }
  }, [showCopilotWelcomeModal, sendAnalyticsEvent, nudgeCategory, analyticsLabel])

  const handleClose = useCallback(() => {
    sendAnalytics('dismiss')
    if (dismissPath) {
      void verifiedFetch(dismissPath, {method: 'POST'})
    }
  }, [sendAnalytics, dismissPath])

  const handleEvent = useCallback(
    (eventName: string, data?: Record<string, unknown>) => {
      if (eventName === 'tab_clicked') {
        const tabIndex = TAB_TITLES.indexOf(data?.tabName as string)
        if (tabIndex >= 0) {
          activeTabIndexRef.current = tabIndex
          sendAnalytics((data?.tabName as string).toLowerCase().replace(/[,\s]+/g, '_'))
        }
      }
      if (eventName === 'main_cta1_clicked') {
        const slideNumber = activeTabIndexRef.current + 1
        sendAnalytics(`slide_${slideNumber}_get_started`)
      }
      if (eventName === 'tab_dropdown_opened') {
        sendAnalytics('slide_1_dropdown_opened')
      }
      if (eventName === 'tab_dropdown_input_copied') {
        sendAnalytics('slide_1_set_up_cli_copy')
      }
      if (eventName === 'tab_dropdown_item_clicked') {
        const id = data?.id as string | undefined
        const actionMap: Record<string, string> = {
          vscode: 'slide_1_set_up_ide_vscode',
          jetbrains: 'slide_1_set_up_ide_jetbrains',
          more: 'slide_1_set_up_ide_more',
        }
        if (id && actionMap[id]) {
          sendAnalytics(actionMap[id])
        }
      }
      if (eventName === 'tab_cta2_clicked') {
        const slideNumber = activeTabIndexRef.current + 1
        const ctaActionMap: Record<number, string> = {
          2: 'slide_2_start_with_agents',
          3: 'slide_3_create_a_custom_agent',
        }
        if (ctaActionMap[slideNumber]) {
          sendAnalytics(ctaActionMap[slideNumber])
        }
        // Both slide 2 and slide 3 navigate via a declarative `href` on the CTA
        // so the base modal does NOT call onClose(). For slide 2 the href points
        // at /in-product-messaging/dismiss-and-redirect, which dismisses the
        // notice on the writer and 302s to /copilot/agents in a single request,
        // avoiding the read-after-write race that would let the modal reappear
        // on the destination page.
      }
    },
    [sendAnalytics],
  )

  if (!showCopilotWelcomeModal) return null

  return (
    <ProductAnnouncement
      announcementId="ccaOnboarding"
      label={copilotPlanName}
      shouldShowMainCta
      shouldShowTabCtas
      onClose={handleClose}
      onModalEvent={handleEvent}
    />
  )
}
