import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import type {CopilotSpace, CopilotSpaceId} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {getCopilotSpacePath} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {COPILOT_SPACES_QUERY_KEY, copilotSpacesQueryKey} from '@github-ui/copilot-spaces/utils/fetch'
import {useMutation, useQueryClient} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

export type Input = {starred: boolean}

export const useStarCopilotSpace = (space: CopilotSpace) => {
  const manager = useChatManager()
  const queryClient = useQueryClient()

  const {
    mutateAsync: starCopilotSpace,
    isPending,
    ...rest
  } = useMutation({
    onSuccess: async () => {
      const spaceId: CopilotSpaceId = {id: space.id, owner: space.owner}
      await queryClient.invalidateQueries({queryKey: copilotSpacesQueryKey(spaceId)})

      return queryClient.invalidateQueries({queryKey: COPILOT_SPACES_QUERY_KEY})
    },
    mutationFn: async (input: Input) => {
      let copilotSpace = space
      if (!copilotSpace) return

      const spaceId: CopilotSpaceId = {id: copilotSpace.id, owner: copilotSpace.owner}
      const url = `${getCopilotSpacePath(spaceId)}/stars`
      const method = input.starred ? 'POST' : 'DELETE'

      const response = await verifiedFetchJSON(url, {
        method,
      })

      if (!response.ok) {
        return
      }

      // since this is the only field that changed
      // we can just do a front end update instead of
      // having to return a whole object.
      copilotSpace = {...copilotSpace, starred: input.starred}

      manager.dispatch({
        type: 'SET_CUSTOM_COPILOT',
        customCopilot: copilotSpace,
      })

      return copilotSpace
    },
  })

  return {
    starCopilotSpace,
    isLoading: isPending,
    ...rest,
  }
}
